PATCH = 48                 # the side of a patch cut around a keypoint (the network looks at its central 32 × 32)


# ====================================================================== preparing a photo (given)

# given — read it and use it, no need to change it
def upright(gray, heading_deg, zoom, size=None):
    """Turn a photo north-up and bring it to the map's scale with a PRIOR heading and zoom (mission 08's like_map,
    with OpenCV). The photo's centre point ((w − 1)/2, (h − 1)/2) lands on the result's centre point.

    Inputs: gray (h, w) uint8 photo; heading_deg (clockwise from north); zoom > 0; size: the result's side in pixels
    (None: round(hypot(w, h) / zoom), big enough for any heading). Returns (img, valid, A): img (size, size) uint8;
    valid (size, size) uint8, 255 where the pixel comes from inside the photo, 0 elsewhere; A (3 × 3) maps a photo
    pixel to the result's pixel (np.linalg.inv(A) maps back).
    Example: upright(np.zeros((480, 640), np.uint8), 0.0, 1.6)[0].shape → (500, 500)
    """
    # from mission 22 — finished: read it, use it, do not change it
    g = to_gray(np.asarray(gray))
    h, w = g.shape
    side = int(round(math.hypot(w, h) / zoom)) if size is None else int(size)
    t = math.radians(heading_deg)
    c, s = math.cos(t), math.sin(t)
    R = np.array([[c, -s], [s, c]]) / zoom                    # photo axes → north-up axes, map scale
    cin = np.array([(w - 1) / 2.0, (h - 1) / 2.0])
    cout = np.array([(side - 1) / 2.0, (side - 1) / 2.0])
    A = np.eye(3)
    A[:2, :2] = R
    A[:2, 2] = cout - R @ cin
    img = cv2.warpAffine(g, A[:2], (side, side), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT)
    valid = cv2.warpAffine(np.full_like(g, 255), A[:2], (side, side), flags=cv2.INTER_NEAREST,
                           borderMode=cv2.BORDER_CONSTANT)
    return img, valid, A


# given — read it and use it, no need to change it
def keypoints(gray, n=1000, margin=PATCH // 2, valid=None):
    """Where to cut patches: the positions of OpenCV's SIFT keypoints (at most n, positions only), without
    duplicates (SIFT gives one point several times when it has several orientations), at least `margin` pixels from
    the border and, when `valid` is given, with the whole patch inside the valid area.

    Returns float32 (N, 2) of (x, y).
    Example: keypoints(np.zeros((100, 100), np.uint8)).shape → (0, 2)
    """
    # from mission 22 — finished: read it, use it, do not change it
    g = to_gray(np.asarray(gray))
    kps = cv2.SIFT_create(int(n)).detect(g, None)
    p = np.array([k.pt for k in kps], dtype=np.float32).reshape(-1, 2)
    if len(p):
        _, first = np.unique(np.round(p * 2), axis=0, return_index=True)
        p = p[np.sort(first)]
    h, w = g.shape
    ok = (p[:, 0] >= margin) & (p[:, 1] >= margin) & (p[:, 0] <= w - 1 - margin) & (p[:, 1] <= h - 1 - margin)
    p = p[ok]
    if valid is not None and len(p):
        inside = cv2.erode((np.asarray(valid) > 0).astype(np.uint8), np.ones((2 * margin + 1, 2 * margin + 1), np.uint8))
        p = p[inside[np.round(p[:, 1]).astype(int), np.round(p[:, 0]).astype(int)] > 0]
    return p


# given — read it and use it, no need to change it
def patches_at(gray, pts, size=PATCH):
    """The size × size grey patches centred on the points (sub-pixel, cv2.getRectSubPix): uint8 (N, size, size),
    ready for learned_desc.describe.

    Example: patches_at(np.zeros((100, 100), np.uint8), [[50, 50], [30.5, 60]]).shape → (2, 48, 48)
    """
    # from mission 22 — finished: read it, use it, do not change it
    g = to_gray(np.asarray(gray))
    p = np.asarray(pts, dtype=np.float32).reshape(-1, 2)
    if len(p) == 0:
        return np.zeros((0, size, size), np.uint8)
    return np.stack([cv2.getRectSubPix(g, (size, size), (float(x), float(y))) for x, y in p])


# given — read it and use it, no need to change it
def sift_pairs(map_gray, photo_gray, ratio=0.8, n=1500):
    """Candidate pairs with SIFT (detect of mission 21, YOUR ratio_test): SIFT needs no prior, because each keypoint
    carries its own scale and orientation. Returns (src, dst): float arrays (K, 2), src[k] in the map, dst[k] in
    the photo.

    Example: sift_pairs(map_gray, photo_gray)[0].shape → (K, 2), K a few hundred on a textured pair
    """
    # from mission 22 — finished: read it, use it, do not change it
    p1, d1 = detect(map_gray, "sift", n)
    p2, d2 = detect(photo_gray, "sift", n)
    if d1 is None or d2 is None:
        return np.zeros((0, 2)), np.zeros((0, 2))
    m = ratio_test(distance_matrix(d1, d2), ratio).reshape(-1, 2)
    return p1[m[:, 0]].astype(np.float64), p2[m[:, 1]].astype(np.float64)


